"""Resolve disposable test assets from source or its isolated install tree."""

from pathlib import Path


def find_test_root(origin: Path = Path(__file__)) -> Path:
    resolved = origin.resolve()
    for candidate in (resolved.parent, *resolved.parents):
        if (candidate / "input" / "test_video.mp4").is_file():
            return candidate
    raise FileNotFoundError(
        f"cannot locate input/test_video.mp4 above test tool path: {resolved}")
